'use strict';
const $ = id => document.getElementById(id);
const motors = Array.from({length:6}, (_,i) => ({name:`AK45-${i+1}`,online:i<2,current:i===0?10.2:i===1?-5.1:0,target:i===0?10.2:i===1?-5.1:0,draft:i===0?12:0,status:'Idle'}));
let selected=0, stopped=false;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function drawList(){ $('motor-list').replaceChildren();motors.forEach((m,i)=>{const b=document.createElement('button');b.type='button';b.className=`motor ${i===selected?'active':''} ${m.online?'':'offline'}`;b.setAttribute('aria-pressed',String(i===selected));b.setAttribute('aria-label',`${m.name}, ${m.online?'연결됨':'연결 안 됨'}`);b.innerHTML=`<span class="motor-icon">⬡</span><span class="motor-info"><strong>${m.name}</strong><small><i class="dot ${m.online?'green':'muted'}"></i>${m.online?'연결됨':'연결 안 됨'}</small></span><span class="motor-angle">${m.online?m.current.toFixed(1)+'°':'—'}</span>`;b.onclick=()=>{selected=i;syncDraft();render();if(!m.online)toast('연결되지 않은 모터입니다. 연결된 모터를 선택하세요.',true);};$('motor-list').append(b);});}
function syncDraft(){const m=motors[selected];$('target').value=m.draft.toFixed(1);$('slider').value=m.draft;$('input-error').textContent='';$('target').removeAttribute('aria-invalid');updateSlider();}
function updateSlider(){const v=Number($('slider').value);$('slider').style.background=`linear-gradient(to right,#639fff ${(v+15)/30*100}%,#2a3749 ${(v+15)/30*100}%)`;}
function render(){const m=motors[selected];drawList();$('selected-name').textContent=m.name;$('status-name').textContent=m.name;$('current').textContent=m.online?m.current.toFixed(1):'—';$('selected-status').textContent=m.online?'● 연결됨':'● 연결 안 됨';$('selected-status').className='badge'+(m.online?' green-badge':'');$('metric-current').innerHTML=m.online?`${m.current.toFixed(1)}<small>°</small>`:'—';$('metric-target').innerHTML=m.online?`${m.target.toFixed(1)}<small>°</small>`:'—';$('metric-difference').innerHTML=m.online?`${Math.abs(m.target-m.current).toFixed(1)}<small>°</small>`:'—';const status=!m.online?'Disconnected':stopped?'Stopped':m.status;const statusLabels={Idle:'대기 중',Moving:'이동 중',Reached:'이동 완료',Disconnected:'연결 안 됨',Stopped:'긴급 정지'};$('motion').textContent='● '+statusLabels[status];$('motion').style.color=status==='Reached'?'#68dcb0':status==='Moving'?'#7db1ff':status==='Stopped'?'#ff9097':'#a4b0bf';$('status-description').textContent=status==='Moving'?'설정한 목표 각도로 이동하고 있습니다':status==='Reached'?'목표 각도에 도착했습니다':status==='Disconnected'?'연결된 모터를 선택하면 제어할 수 있습니다':stopped?'긴급 정지를 해제하면 다시 제어할 수 있습니다':'목표 각도를 설정하고 이동하세요';['target','slider','minus','plus','send'].forEach(id=>$(id).disabled=stopped||!m.online);$('emergency').hidden=!stopped;$('connection').textContent=stopped?'긴급 정지 중':'연결됨';$('connection').previousElementSibling.style.background=stopped?'#f59e0b':'#48d6a0';$('dial-arc').style.opacity=m.online?'1':'.15';$('dial-arc').setAttribute('stroke-dasharray',`${m.online?(m.current+15)/30*405:0} 450`);}
function validate(){const raw=$('target').value;const v=Number(raw);const valid=raw.trim()!==''&&Number.isFinite(v)&&v>=-15&&v<=15;$('input-error').textContent=valid?'':'−15.0°부터 +15.0° 사이의 각도를 입력하세요.';$('target').setAttribute('aria-invalid',String(!valid));return valid;}
$('target').addEventListener('input',()=>{if(validate()){motors[selected].draft=Number($('target').value);$('slider').value=motors[selected].draft;updateSlider();}});
$('target').addEventListener('change',()=>{if(validate())syncDraft();});
$('slider').addEventListener('input',()=>{motors[selected].draft=Number($('slider').value);syncDraft();});
function step(delta){const v=Number($('target').value);motors[selected].draft=Math.round(Math.min(15,Math.max(-15,(Number.isFinite(v)?v:0)+delta))*10)/10;syncDraft();}
$('minus').onclick=()=>step(-.1);$('plus').onclick=()=>step(.1);
$('command-form').addEventListener('submit',event=>{event.preventDefault();const m=motors[selected];if(stopped)return;if(!m.online){toast('연결되지 않은 모터입니다. 연결된 모터를 선택하세요.',true);return;}if(!validate()){toast('목표 각도는 −15.0°부터 +15.0°까지 입력할 수 있습니다.',true);return;}m.target=Math.round(Number($('target').value)*10)/10;m.draft=m.target;m.status=Math.abs(m.current-m.target)<.05?'Reached':'Moving';syncDraft();render();toast(`이동 요청을 전송했습니다 · ${m.name} → ${m.target.toFixed(1)}°`);});
$('stop').onclick=()=>{stopped=true;motors.forEach(m=>{if(m.online)m.status='Idle';});render();toast('긴급 정지했습니다. 모든 모터의 이동을 멈췄습니다.',true);};
$('reset').onclick=()=>{stopped=false;motors.forEach(m=>{m.status='Idle';});render();toast('긴급 정지를 해제했습니다. 이동 버튼을 누르면 다시 움직입니다.');};
setInterval(()=>{if(stopped)return;let changed=false;motors.forEach(m=>{if(m.status!=='Moving')return;const diff=m.target-m.current;m.current=Math.round((Math.abs(diff)<=.2?m.target:m.current+Math.sign(diff)*.2)*10)/10;if(m.current===m.target)m.status='Reached';changed=true;});if(changed)render();},100);
syncDraft();render();
